const response = $json;
const rows = Array.isArray(response?.data) ? response.data : Array.isArray(response) ? response : [];

const normalizeText = (value) => String(value ?? "").trim();
const normalizeLower = (value) => normalizeText(value).toLowerCase();
const normalizeUpper = (value) => normalizeText(value).toUpperCase();

const findings = rows.map((item) => {
  const attrs = item.attributes || item;
  return {
    provider: normalizeText(attrs.provider || attrs.provider_uid || attrs.account_id || attrs.account || attrs.provider_id || "unknown"),
    service: normalizeLower(attrs.service || attrs.service_name),
    severity: normalizeLower(attrs.severity),
    status: normalizeUpper(attrs.status || attrs.state),
    check: normalizeText(attrs.check_id || attrs.check || attrs.uid || attrs.finding_uid || "unknown-check"),
    title: normalizeText(attrs.title || attrs.description || attrs.check_id || "Finding without title"),
    region: normalizeText(attrs.region || attrs.region_name || "global"),
    resourceType: normalizeText(attrs.resource_type || attrs.resource_kind || ""),
    resource: normalizeText(attrs.resource_uid || attrs.resource_id || attrs.resource || "")
  };
}).filter((finding) => {
  const allowedServices = ["iam", "s3", "cloudtrail"];
  const allowedSeverity = ["critical", "high"];
  const failedStatuses = ["FAIL", "FAILED", "OPEN"];
  return allowedServices.includes(finding.service)
    && allowedSeverity.includes(finding.severity)
    && failedStatuses.includes(finding.status);
});

const countBy = (items, key) => items.reduce((acc, item) => {
  const value = item[key] || "unknown";
  acc[value] = (acc[value] || 0) + 1;
  return acc;
}, {});

const topEntries = (counts, limit = 10) => Object.entries(counts)
  .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
  .slice(0, limit)
  .map(([name, count]) => ({ name, count }));

const bySeverity = countBy(findings, "severity");
const byService = countBy(findings, "service");
const byProvider = countBy(findings, "provider");
const byCheck = countBy(findings, "check");

const topFindings = findings
  .sort((a, b) => {
    const severityRank = { critical: 0, high: 1 };
    return (severityRank[a.severity] ?? 9) - (severityRank[b.severity] ?? 9)
      || a.service.localeCompare(b.service)
      || a.check.localeCompare(b.check);
  })
  .slice(0, 40)
  .map((finding) => ({
    provider: finding.provider,
    service: finding.service,
    severity: finding.severity,
    check: finding.check,
    title: finding.title.slice(0, 180),
    region: finding.region,
    resourceType: finding.resourceType
  }));

return [{
  json: {
    generatedAt: new Date().toISOString(),
    prowlerUrl: $env.PROWLER_APP_URL || "",
    scope: {
      provider: "aws",
      services: ["iam", "s3", "cloudtrail"],
      severities: ["critical", "high"],
      statuses: ["FAIL", "FAILED", "OPEN"],
      version: "v1"
    },
    totalFindings: findings.length,
    bySeverity,
    byService,
    topProviders: topEntries(byProvider, 10),
    topChecks: topEntries(byCheck, 10),
    topFindings
  }
}];

const pickSummary = (payload) => {
  if (!payload || typeof payload !== "object") return payload;

  if (payload.summary) return payload.summary;
  if (payload.message) return payload.message;
  if (payload.output_text) return payload.output_text;
  if (payload.output) return payload.output;
  if (payload.text) return payload.text;

  if (payload.data?.summary) return payload.data.summary;
  if (payload.result?.summary) return payload.result.summary;
  if (payload.choices?.[0]?.message?.content) return payload.choices[0].message.content;
  if (payload.choices?.[0]?.text) return payload.choices[0].text;

  return JSON.stringify(payload);
};

const raw = pickSummary($json);
const maxChars = 24000;
let text = String(raw || "").trim();

if (!text) {
  text = "**Resumo semanal Prowler**\n\nNao foi possivel gerar o resumo automatico. Verifique o workflow n8n e o endpoint do agente.";
}

if (text.length > maxChars) {
  text = text.slice(0, maxChars - 180) + "\n\n_Mensagem truncada para respeitar limite de tamanho do Teams. Consulte o Prowler App para detalhes completos._";
}

return [{ json: { text } }];
